from sympy.simplify.simplify import simplify

def decide(e):
    """True/False if ``e`` is (not) zero, None if that is unknown"""
    if e.is_zero:
        return True
    if e.is_number:
        # an exact number: decide it numerically
        return e.evalf(chop=True) == S.Zero
    if e.is_zero is False:
        return False
    return None

